public int minInsertions(String s) {
    int open = 0; // To track the number of unmatched '('
    int insertions = 0; // To track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // If we encounter a ')', we need to match it with a '('
            if (open > 0) {
                open--; // Match with an existing '('
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
            // Check if the next character is also a ')', if so, we can match them together
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it is matched
            } else {
                insertions++; // Need to insert a ')' to match the current '('
            }
        }
    }

    // Add the remaining unmatched '('
    insertions += open * 2;

    return insertions;
}

